func maximumCandies(candies []int, k int64) int {
	return sort.Search(1e7, func(v int) bool {
		v++
		var cnt int64
		for _, x := range candies {
			cnt += int64(x / v)
		}
		return cnt < k
	})
}

function maximumCandies(candies: number[], k: number): number {
    let [l, r] = [0, Math.max(...candies)];
    while (l < r) {
        const mid = (l + r + 1) >> 1;
        const cnt = candies.reduce((acc, cur) => acc + Math.floor(cur / mid), 0);
        if (cnt >= k) {
            l = mid;
        } else {
            r = mid - 1;
        }
    }
    return l;
}

//Editorial: https://leetcode.com/problems/maximum-candies-allocated-to-k-children/discuss/1908738/C%2B%2B-Easy-solution-with-Explanation
class Solution {
public:
    typedef long long ll;
    int solve(vector<int> nums,ll mid,ll k)
    {
        ll cnt=0;
        for(auto it:nums)
        {
            cnt+=it/mid;
            if(cnt>=k)
                return 1;
        }
        return 0;

    }
    int maximumCandies(vector<int>& nums, long long k) {
        int low=1,high=*max_element(nums.begin(),nums.end());
        int ans=0;
        while(low<=high)
        {
            ll mid=low+(high-low)/2;
            if(solve(nums,mid,k))
            {
                ans=mid;
                low=mid+1;
            }
            else
                high=mid-1;
        }
        return ans;
    }
};
